import {readFileSync, readdirSync, existsSync} from 'node:fs';
import {join} from 'node:path';
import assert from 'node:assert/strict';

const root = process.cwd();

// 侧栏现状：三条全部 autogenerated，sidebars.ts 只做挂载。
// 结构真相源 = docs/ 目录 + 各分组 _category_.json + frontmatter sidebar_position。

const requiredMarkers = {
  'sidebars.ts': [
    "dirName: 'resources'",
    "dirName: 'notes'",
    "dirName: 'application-notes'",
    "type: 'autogenerated'",
  ],
};

const forbiddenMarkers = {
  // 手写侧栏时代的残留，出现即说明有人把旧结构写回来了
  'sidebars.ts': [
    "label: '应用沉淀文档'",
    "label: '流程文档'",
    '学习地图与路径',
    'Harness / Coding Agent',
    '架构与生产化',
    '源码与真实系统',
  ],
};

// 资源导航五组分组（目录 -> 期望标签）
const resourceGroups = {
  tutorials: '通用 Agent 系统教程',
  references: '模式与生产参考',
  coding: 'AI 编程上手',
  mechanism: 'Coding Agent 机制拆解',
  systems: '真实系统源码',
};

for (const [relativePath, markers] of Object.entries(requiredMarkers)) {
  const absolutePath = join(root, relativePath);
  const content = readFileSync(absolutePath, 'utf8');

  for (const marker of markers) {
    assert.match(
      content,
      new RegExp(marker.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')),
      `${relativePath} is missing marker: ${marker}`,
    );
  }
}

for (const [relativePath, markers] of Object.entries(forbiddenMarkers)) {
  const absolutePath = join(root, relativePath);
  const content = readFileSync(absolutePath, 'utf8');

  for (const marker of markers) {
    assert.doesNotMatch(
      content,
      new RegExp(marker.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')),
      `${relativePath} should not contain marker: ${marker}`,
    );
  }
}

for (const [dir, label] of Object.entries(resourceGroups)) {
  const groupDir = join(root, 'docs', 'resources', dir);
  const categoryFile = join(groupDir, '_category_.json');

  assert.ok(existsSync(categoryFile), `missing ${categoryFile}`);

  const category = JSON.parse(readFileSync(categoryFile, 'utf8'));
  assert.equal(category.label, label, `${categoryFile} label mismatch`);

  // 每组至少一条资源（<slug>/index.md）
  const hasResource = readdirSync(groupDir, {withFileTypes: true}).some(
    (entry) =>
      entry.isDirectory() && existsSync(join(groupDir, entry.name, 'index.md')),
  );
  assert.ok(hasResource, `docs/resources/${dir}/ has no resource pages`);
}

console.log('Page redesign content contract passed.');
